from ansible.module_utils.sysctl import get_sysctl

class FakeModule:
    def get_bin_path(self, name):
        assert name == 'sysctl'
        return '/sbin/sysctl'

    def run_command(self, cmd):
        assert cmd == ['/sbin/sysctl', 'net.ipv4.ip_forward', 'kernel.hostname']
        return 0, 'net.ipv4.ip_forward = 1\nkernel.hostname: testhost\n', ''

    def warn(self, msg):
        raise AssertionError(msg)

result = get_sysctl(FakeModule(), ['net.ipv4.ip_forward', 'kernel.hostname'])
assert result == {'net.ipv4.ip_forward': '1', 'kernel.hostname': 'testhost'}

